export const title = "How to Keep a Desk Lamp From Disturbing a Sleeping Roommate";
export const metaTitle = "How to Keep a Desk Lamp From Disturbing a";
export const metaDescription = "Position a desk lamp around a sleeping roommate by checking direct light, reflected light, task coverage, and controls. A research-based guide from DeskFinds.";
export const author = "Jamie Cole, Lead Product Researcher";
